// Checks the request body and normalizes its fields. Invalid requests get a 400 with every problem listed.
const body = $input.first().json.body ?? {};
const text = (value) => (typeof value === 'string' ? value.trim() : '');

const project = text(body.project);
const branch = text(body.branch) || 'main';
const commit = text(body.commit);
const buildUrl = text(body.build_url);
const junitXml = typeof body.junit_xml === 'string' ? body.junit_xml : '';
const minPassRate = body.min_pass_rate ?? 95;

const errors = [];
if (!project) errors.push('project is required');
else if (!/^\S{1,120}$/.test(project)) errors.push('project must be 1-120 characters with no spaces');
if (!/^\S{1,200}$/.test(branch)) errors.push('branch must be 1-200 characters with no spaces');
if (commit && !/^\S{1,64}$/.test(commit)) errors.push('commit must be 1-64 characters with no spaces');
if (buildUrl && !/^https?:\/\/\S+$/.test(buildUrl)) errors.push('build_url must be an http(s) URL');
if (!junitXml.trim()) errors.push('junit_xml is required: send the JUnit XML report as a string');
else if (junitXml.length > 5 * 1024 * 1024) errors.push('junit_xml is larger than 5 MB');
if (typeof minPassRate !== 'number' || !Number.isFinite(minPassRate) || minPassRate < 0 || minPassRate > 100) {
  errors.push('min_pass_rate must be a number from 0 to 100');
}

if (errors.length > 0) {
  return [{ json: { ok: false, status_code: 400, error: 'Invalid request', details: errors } }];
}
return [{
  json: { ok: true, project, branch, commit, build_url: buildUrl, min_pass_rate: minPassRate, junit_xml: junitXml },
}];

// Turns the parsed JUnit XML into one row per test case, plus run totals.
// Handles <testsuites> and <testsuite> roots, nested suites, and Maven Surefire reruns
// (<flakyFailure>/<flakyError>: the test failed, then passed when it was rerun).
const request = $('Validate request').first().json;
const doc = $input.first().json;

// When the XML can't be parsed, the XML node outputs an empty item (alwaysOutputData is on).
// It should output the parser error instead, but in n8n 2.40 its "continue on error" setting
// drops that item, so check here and handle both shapes.
const keys = Object.keys(doc);
if (keys.length === 0 || (keys.length === 1 && typeof doc.error === 'string')) {
  const reason = typeof doc.error === 'string'
    ? doc.error.split('\n')[0]
    : 'The report is not well-formed XML, for example a truncated file or an unclosed tag';
  return [{ json: { ok: false, status_code: 400, error: 'junit_xml is not valid XML', details: [reason] } }];
}

const list = (value) => (value === undefined || value === null ? [] : Array.isArray(value) ? value : [value]);
const attr = (node, key) => (node && typeof node === 'object' && node.$ ? node.$[key] : undefined);
const messageOf = (node) => {
  if (node === undefined || node === null) return null;
  if (typeof node === 'string') return node.trim() || null;
  return attr(node, 'message') ?? (typeof node._ === 'string' ? node._.trim() : null);
};

const suites = [];
const collect = (parent) => {
  for (const suite of list(parent.testsuite)) {
    suites.push(suite);
    collect(suite);
  }
};
for (const root of list(doc.testsuites)) collect(root);
collect(doc);

const tests = [];
for (const suite of suites) {
  const suiteName = attr(suite, 'name') ?? '';
  for (const testcase of list(suite.testcase)) {
    const name = attr(testcase, 'name') ?? '(unnamed)';
    const classname = attr(testcase, 'classname') || suiteName;
    const failure = list(testcase.failure)[0];
    const error = list(testcase.error)[0];
    const skipped = list(testcase.skipped)[0];
    const rerun = list(testcase.flakyFailure)[0] ?? list(testcase.flakyError)[0];

    let status = 'passed';
    let message = null;
    if (failure !== undefined) [status, message] = ['failed', messageOf(failure)];
    else if (error !== undefined) [status, message] = ['error', messageOf(error)];
    else if (skipped !== undefined) [status, message] = ['skipped', messageOf(skipped)];
    else if (rerun !== undefined) message = messageOf(rerun);

    const seconds = Number.parseFloat(attr(testcase, 'time') ?? '0');
    tests.push({
      test_id: `${classname}::${name}`,
      suite: suiteName,
      name,
      status,
      duration_ms: Number.isFinite(seconds) ? Math.round(seconds * 1000) : 0,
      message: message ? message.slice(0, 2000) : null,
      retried: status === 'passed' && rerun !== undefined,
    });
  }
}

if (tests.length === 0) {
  return [{
    json: { ok: false, status_code: 422, error: 'No test cases found', details: ['The report has no <testcase> elements'] },
  }];
}

const count = (...statuses) => tests.filter((test) => statuses.includes(test.status)).length;
const { junit_xml, ...metadata } = request;
return [{
  json: {
    ...metadata,
    total: tests.length,
    passed: count('passed'),
    failed: count('failed', 'error'),
    skipped: count('skipped'),
    duration_ms: tests.reduce((sum, test) => sum + test.duration_ms, 0),
    tests,
  },
}];

// Applies the gate policy and builds the response.
// The gate fails when:
//   - a test fails that didn't fail in the previous run, unless it's a known flaky test, or
//   - the pass rate (skipped tests excluded) is below min_pass_rate.
// Known flaky tests are reported but never block, so one unstable test can't hold up every build.
const run = $('Normalize results').first().json;
const saved = $('Save run').first().json;
const history = $input.first().json;

const executed = run.total - run.skipped;
const passRate = executed > 0 ? Math.round((run.passed / executed) * 10000) / 100 : 100;
const flakyIds = new Set(history.flaky.map((test) => test.test_id));
const blocking = history.new_failures.filter((id) => !flakyIds.has(id));

const reasons = [];
if (blocking.length > 0) {
  const shown = blocking.slice(0, 5).join(', ') + (blocking.length > 5 ? ` and ${blocking.length - 5} more` : '');
  reasons.push(`${blocking.length} new failure${blocking.length === 1 ? '' : 's'}: ${shown}`);
}
if (passRate < run.min_pass_rate) {
  reasons.push(`pass rate ${passRate}% is below the required ${run.min_pass_rate}%`);
}
const gate = reasons.length === 0 ? 'passed' : 'failed';

const failures = run.tests
  .filter((test) => test.status === 'failed' || test.status === 'error')
  .slice(0, 50)
  .map((test) => ({ test_id: test.test_id, status: test.status, message: test.message, flaky: flakyIds.has(test.test_id) }));

const headers = $('Receive results').first().json.headers ?? {};
const origin = `${headers['x-forwarded-proto'] ?? 'http'}://${headers['x-forwarded-host'] ?? headers.host ?? 'localhost:5678'}`;
const dashboardUrl = `${origin}/webhook/qa/dashboard?project=${encodeURIComponent(run.project)}&branch=${encodeURIComponent(run.branch)}`;

// Markdown summary, e.g. for $GITHUB_STEP_SUMMARY.
const code = (text) => '`' + String(text).replace(/`/g, "'") + '`';
const firstLine = (text) => (text ? String(text).split('\n')[0].slice(0, 160) : '');
const lines = [
  `## ${gate === 'passed' ? '✅' : '❌'} Quality gate ${gate}: ${run.project} (${run.branch})`,
  '',
  '| Total | Passed | Failed | Skipped | Pass rate | Duration |',
  '|---:|---:|---:|---:|---:|---:|',
  `| ${run.total} | ${run.passed} | ${run.failed} | ${run.skipped} | ${passRate}% (min ${run.min_pass_rate}%) | ${(run.duration_ms / 1000).toFixed(1)} s |`,
];
if (reasons.length > 0) lines.push('', `**Why it failed:** ${reasons.join('; ')}.`);
const section = (title, entries) => {
  if (entries.length > 0) lines.push('', `### ${title} (${entries.length})`, '', ...entries);
};
section('New failures', history.new_failures.map((id) => {
  const failure = failures.find((f) => f.test_id === id);
  const note = flakyIds.has(id) ? ' _(known flaky, not blocking)_' : '';
  return `- ${code(id)}${note}${failure?.message ? ` — ${firstLine(failure.message)}` : ''}`;
}));
section('Still failing', history.still_failing.map((id) => `- ${code(id)}`));
section('Flaky', history.flaky.map((test) =>
  `- ${code(test.test_id)} — ${test.flips} pass/fail flips in the last ${history.runs_in_window} runs` +
  (test.passed_on_retry > 0 ? `, passed on retry ${test.passed_on_retry} time${test.passed_on_retry === 1 ? '' : 's'}` : '')));
section('Fixed since the previous run', history.fixed.map((id) => `- ${code(id)}`));

return [{
  json: {
    run_id: Number(saved.run_id),
    previous_run_id: history.previous_run_id === null ? null : Number(history.previous_run_id),
    project: run.project,
    branch: run.branch,
    commit: run.commit || null,
    gate,
    reasons,
    stats: {
      total: run.total,
      passed: run.passed,
      failed: run.failed,
      skipped: run.skipped,
      pass_rate: passRate,
      min_pass_rate: run.min_pass_rate,
      duration_ms: run.duration_ms,
    },
    new_failures: history.new_failures,
    still_failing: history.still_failing,
    fixed: history.fixed,
    flaky: history.flaky,
    failures,
    dashboard_url: dashboardUrl,
    summary_markdown: lines.join('\n'),
  },
}];
